

/**
 * 能量触发的免费游戏
 */


cc.Class({
    extends: cc.Component,

    properties: {
        bgs: [cc.SpriteFrame],
        freegamespine:cc.Node,
        _midState:"animation3",
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._mid_ani = cc.find('Canvas/safe_node/slots/mid_ani')

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_STOP_MOVE, this.playStop,this);

        let btnstart = cc.find('node/energyfreegame_start/middimage/btn_start',this.node)
        Global.btnClickEvent(btnstart,this.startEnergyFreeGame,this)

        let btncollect = cc.find('node/energyfreegame_end/middimage/btn_collect',this.node)
        Global.btnClickEvent(btncollect,this.collectEnergyFreeGame,this)

        this._soundCfg = cc.vv.gameData.getGameCfg().soundCfg;
    },

    
    //控制老虎位置
    setTigerPos:function(isshow){
        let node_tiger = cc.find('safe_node/tiger',this.node);
        let posy = isshow?-155:-200; 
        node_tiger.setPosition(0,posy);
    },

    //控制能量界面的显示/隐藏
    showEnergyUI:function(isshow){
        let node_energy = cc.find('safe_node/node_energy',this.node)
        node_energy.active = isshow
        this.setTigerPos(isshow);
    },

    //显示能量免费游戏
    showEngnerFreeGame:function(bShow,etype){
        //显示免费次数节点
        this.showFreeTimes(bShow);

        //免费游戏背景图
        this.showGameBg(bShow)
    },

    showGameBg:function(bShow){
        
        let fileName = 'theme115_base_bg'
        if(bShow){
            fileName = 'theme115_free_bg'
        }
        let gameDir = cc.vv.gameData.getGameCfg().gameDir
        cc.loader.loadRes(gameDir + 'img/'+fileName,cc.SpriteFrame,(err,data) => {
            if(!err){
                let bg = cc.find('Canvas/safe_node/bg')
                bg.getComponent(cc.Sprite).spriteFrame = data
            }
        })
    },

    onEventShowEngFreeGame:function(data){
        let val = data.detail
        if(val.isshow == undefined)
            return;
        this.showEngnerFreeGame(val.isshow,val.etype)
    },

    //开始能量免费游戏
    onEventStartSpin:function(){
        if(this.eType == 2){
            this.showEnergyUI(false);
        }
    },

    //////////////////////////////////////////////////////////////////
    //能量免费游戏开始
    energyFreeGameStart(engData){
        this.showEnergyFreeUI(true);
    },

    async spinEnd(){
        return new Promise((success)=>{
            let gameinfo = cc.vv.gameData.getGameInfo();
            if(gameinfo.booms){
                success();
                return;
            }
            if(gameinfo.allFreeCnt > 0){
                if(gameinfo.freeCnt >= 0 ){
                    this.changeWildMult(gameinfo.collect.mult);
                    this.lineStop();
                }
                this.scheduleOnce(()=>{
                    success();
                },1.5)
            }else{
                success();
            } 
        });
    },

    //能量旋转结束(播放线结束)
    async playLineOver(){
        return new Promise((success)=>{
            this._nextpromise = success;
            console.log("###能量游戏播放结束");
            let gameinfo = cc.vv.gameData.getGameInfo();
            if(gameinfo.booms||gameinfo.allFreeCnt == 0){
                success();
                return;
            }
            console.log("###免费次数 "+gameinfo.freeCnt);
            if(gameinfo.allFreeCnt > 0){
                if(gameinfo.freeCnt > 0 ){
                    success();
                }else{
                    cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
                    this.showEnergyFreeUI(false);
                }
            }
        })
    },

    //播放地图大关中间动画
    playMidAniClose(){
        if(this._mid_ani.active){
            Global.playHSEffect('reel_hide');
            this.playMidAnimation('animation3');
        }
    },

    //修改倍率
    changeWildMult(mult){
        for(let i=1;i<4;i++){
            let midspine = cc.find("lbl_mul"+i,this._mid_ani);
            if(mult == 0){
                midspine.active = false;
            }else{
                cc.vv.gameData.playSpine(midspine,'animation'+mult,true);
            }
        }
    },

    //旋转停止
    playStop(){
           
    },

    //播放中间动画
    lineStop(){
        let gameinfo = cc.vv.gameData.getGameInfo();
        if(gameinfo.booms)
            return;
        console.log("###免费次数 "+gameinfo.freeCnt);
        if(gameinfo.freeCnt >= 0){
            Global.playHSEffect('reel_appear');
            this.playMidAnimation('animation2');
        }
    },

    //showstart true显示开始 false显示结束
    showEnergyFreeUI(showstart){
        cc.find("node",this.node).active = true;
        cc.find("node/energyfreegame_start",this.node).active = showstart;
        cc.find("node/energyfreegame_end",this.node).active = !showstart;
        if(showstart){
            //进入数据
            Global.playHSEffect('bonus_dialog_start_show');
            let engData = cc.vv.gameData.getCollectData();
            let freetime = cc.find("node/energyfreegame_start/middimage/up/freetime",this.node);
            freetime.getComponent(cc.Label).string = engData.free;
            this.openStartUIAni();
        }else{
            //结束数据
            Global.playHSEffect('bonus_dialog_collect_show');
            cc.vv.gameData.setWaitOperate(true);
            let gameinfo = cc.vv.gameData.getGameInfo();
            let reward = cc.find("node/energyfreegame_end/middimage/collectbg/rewardnum",this.node);
            Global.doRoallNumEff(reward,0,gameinfo.freeWinCoin,1.5,null,null,0,true)
            this.openCollectUIAni();
        }
    },

    //增加开始结束界面动画展示
    async openStartUIAni(){
        let startnode = cc.find("node/energyfreegame_start",this.node);
        let topnode = cc.find('topimage',startnode);
        let mainobj = cc.find('middimage',startnode);
        let toptext = cc.find('toptext',mainobj);
        let btnstart = cc.find('btn_start',mainobj);
        let upnode = cc.find('up',mainobj);
        let downnode = cc.find('down',mainobj);
        mainobj.position = cc.v2(0,910);
        toptext.position = cc.v2(0,100);
        toptext.scale = 0;
        upnode.scale = 0;
        downnode.scale = 0;
        btnstart.scale = 0;
        topnode.position = cc.v2(0,800);
        cc.tween(topnode).to(0.3,{position:cc.v2(0,300)},{easing:'backIn'}).call(()=>{
            cc.tween(mainobj).to(0.3,{position:cc.v2(0,-38)}).call(()=>{   
                cc.tween(toptext).to(0.3,{position:cc.v2(0,178),scale:0.5}).start();
                cc.tween(upnode).to(0.3,{scale:0.5},{easing:'backIn'}).call(()=>{
                    cc.tween(downnode).to(0.3,{scale:0.5},{easing:'backIn'}).call(()=>{
                        cc.tween(btnstart).to(0.3,{scale:1.5},{easing:'backIn'}).call(()=>{
    
                        }).start();
                    }).start();
                }).start();
            }).start();
        }).start();
        this.setMultShow(mainobj);

        await cc.vv.gameData.awaitTime(2);

        cc.vv.gameData.checkAutoPlay(btnstart, ()=>{
            Global.playHSEffect(this._soundCfg.free_dialog_click);
            this.sendEnergyFreeGameStart();
            cc.find("node",this.node).active = false;
            Global.playHSEffect('transition_free');
            cc.vv.gameData.playSpine(this.freegamespine,'animation',false,()=>{
                this.reconnectEnterFreeGame();
            })
        });
    },

    //设置获取倍率显示
    setMultShow(middnode){
        let engData = cc.vv.gameData.getCollectData();
        let mults = this.getMultArr(engData.idx);
        for(let i=1;i<4;i++){
            cc.find('down/bg1/ratiotext'+i,middnode).getComponent(cc.Label).string = mults[0]+'X';
            cc.find('down/bg2/ratiotext'+i,middnode).getComponent(cc.Label).string = mults[1]+"X";
        }
    },

    //获取倍率数组
    getMultArr(idx){
        switch (idx) {
            case 2:return [2,5];
            case 7:return [2,10];
            case 13:return [3,25];
            case 20:return [5,100];
            default:return [2,5];
        }
    },

    //增加结束界面动画展示
    async openCollectUIAni(){
        let startnode = cc.find("node/energyfreegame_end",this.node);
        let topnode = cc.find('topimage',startnode);
        let mainobj = cc.find('middimage',startnode);
        let toptext = cc.find('toptext',mainobj);
        let btnstart = cc.find('btn_collect',mainobj);
        let upnode = cc.find('youwin',mainobj);
        let downnode = cc.find('collectbg',mainobj);
        mainobj.position = cc.v2(0,910);
        toptext.position = cc.v2(0,0);
        toptext.scale = 0;
        upnode.scale = 0;
        downnode.scale = 0;
        btnstart.scale = 0;
        topnode.position = cc.v2(0,800);
        cc.tween(topnode).to(0.3,{position:cc.v2(0,300)},{easing:'backOut'}).call(()=>{
            cc.tween(mainobj).to(0.3,{position:cc.v2(0,-68)}).call(()=>{   
                cc.tween(toptext).to(0.3,{position:cc.v2(0,106),scale:0.5}).start();
                cc.tween(upnode).to(0.3,{scale:0.5},{easing:'backOut'}).call(()=>{
                    cc.tween(downnode).to(0.3,{scale:0.5},{easing:'backOut'}).call(()=>{
                        cc.tween(btnstart).to(0.3,{scale:1.5},{easing:'backOut'}).call(()=>{
    
                        }).start();
                    }).start();
                }).start();
            }).start();
        }).start();

        await cc.vv.gameData.awaitTime(2);

        cc.vv.gameData.checkAutoPlay(btnstart, ()=>{
            Global.playHSEffect(this._soundCfg.free_dialog_click);
            Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_ENERGYGAME_OperationOVER,{isshow:false,etype:0});
            this.node.active = false;
            let self = this;
            Global.SlotsSoundMgr.stopBgm();
            Global.playHSEffect('transition_free');
            cc.vv.gameData.playSpine(this.freegamespine,'animation',false,()=>{
                //免费游戏结束
                self.changeGameBackimage(false);
                self.changeEnergyFreeGameState(false);
                self.showFreeTimes(false);
                cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle");
                cc.vv.gameData.GetTopScript().StopMove();
                cc.vv.gameData.setWaitOperate(false);
                if(this._nextpromise)this._nextpromise();
            })
        });
    },

    //开始能量免费游戏
    startEnergyFreeGame(){
        let startnode = cc.find("node/energyfreegame_end",this.node);
        let mainobj = cc.find('middimage',startnode);
        let btnstart = cc.find('btn_collect',mainobj);
        btnstart.stopAllActions();
        Global.playHSEffect(this._soundCfg.free_dialog_click);
        this.sendEnergyFreeGameStart();
        cc.find("node",this.node).active = false;
        Global.playHSEffect('transition_free');
        cc.vv.gameData.playSpine(this.freegamespine,'animation',false,()=>{
            this.reconnectEnterFreeGame();
        })
    },

    //断线重连直接开始免费游戏
    reconnectEnterFreeGame(){
        this.changeGameBackimage(true);
        //开始能量免费游戏
        this.changeEnergyFreeGameState(true);
        //
        this.showFreeTimes(true);
        //开始旋转
        //this.handSpine();
        this.sendSpin();
        Global.SlotsSoundMgr.playBgm('free_bgm');
    },

    //发送能量免费游戏进入
    sendEnergyFreeGameStart(){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.data = {}
        req.data.rtype = 2
        req.gameid = cc.vv.gameData.getGameId()
        cc.vv.NetManager.send(req,true);
    },

    //手动旋转
    handSpine(){
        this.scheduleOnce(()=>{
            cc.find('Canvas/safe_node/slots').getComponent('LuckyCat_Slots').CanDoNextRound();
        },1);
    },
    //开始旋转
    sendSpin(){
        cc.vv.gameData.GetBottomScript().SendSpinReq();
    },
    //结束收集金币
    collectEnergyFreeGame(){
        let startnode = cc.find("node/energyfreegame_end",this.node);
        let mainobj = cc.find('middimage',startnode);
        let btnstart = cc.find('btn_collect',mainobj);
        btnstart.stopAllActions();
        Global.playHSEffect(this._soundCfg.free_dialog_click);
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_ENERGYGAME_OperationOVER,{isshow:false,etype:0});
        this.node.active = false;
        let self = this;
        Global.SlotsSoundMgr.stopBgm();
        Global.playHSEffect('transition_free');
        cc.vv.gameData.playSpine(this.freegamespine,'animation',false,()=>{
            //免费游戏结束
            self.changeGameBackimage(false);
            self.changeEnergyFreeGameState(false);
            self.showFreeTimes(false);
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle");
            cc.vv.gameData.GetTopScript().StopMove();
            cc.vv.gameData.setWaitOperate(false);
            if(this._nextpromise)this._nextpromise();
        })
    },

    //切换游戏背景
    changeGameBackimage(isfree){
        let bg = cc.find("Canvas/safe_node/bg").getComponent(cc.Sprite);
        if(isfree){
            bg.spriteFrame = this.bgs[1];
        }else{
            bg.spriteFrame = this.bgs[0];
        }
    },

    //切换能量免费游戏状态
    changeEnergyFreeGameState(isenergy){
        cc.find('Canvas/safe_node/slots/mid_ani').active = isenergy;
        cc.find("Canvas/safe_node/node_energy/energyfreemask").active = isenergy;
        cc.find("Canvas/safe_node/node_energy/spr_left").active = !isenergy;
    },

    //播放中间动画 3关上 2打开
    playMidAnimation(aniname){
        if(this._midState == aniname)
            return;
        let isshow = aniname == "animation2"?true:false;
        this.controlMultShow(isshow);
        this._midState = aniname;
        let midspine = cc.find("node_zu",this._mid_ani);
        cc.vv.gameData.playSpine(midspine,aniname,false,()=>{
            this._midState = "";
        })
    },

    //控制倍率
    controlMultShow(isshow){
        for(let i=1;i<4;i++){
            cc.find('lbl_mul'+i,this._mid_ani).active = isshow;
        }
    },

    //展示免费次数
    showFreeTimes(bshow){
        if(bshow){
            //初始展示免费次数
            let collect = cc.vv.gameData.getCollectData();
            if(collect){
                let freetime = cc.vv.gameData.GetFreeTime();
                cc.vv.gameData.GetBottomScript().ShowFreeModel(true,freetime+1,collect.free)
            }
        }else{
            cc.vv.gameData.GetBottomScript().ShowFreeModel(false)
        }
    },

   

    //能量大关/小关游戏结束
    onEnergyGameOver:function(){

    },

});
