/**
 * 游戏自己的gamedata
 */
let BigGate = [2,7,13,20]
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        _collectData:null,
        needBet   : 0,      //需要押注
    },

    //deskInfo进入游戏获得的服务端数据
    init(deskInfo,gameId,gameJackpot){
        this._super(deskInfo,gameId,gameJackpot);
         this._collectData = this._deskInfo.collect;
         this._selectData = this._deskInfo.select;
         this.needBet = this._collectData.min;
         this._boomsData = this._deskInfo.booms;
     },

      //注册event
    RegisterEvent(){
        this._super();
        this._EventId.LuckyCat_UNLOCK_ENERGY = 'LuckyCat_UNLOCK_ENERGY'
    },

     OnRcvNetSpine:function(msg){
        // msg =  {"resultCards":[2,9,13,4,5,1,9,13,5,7,7,4,13,2,7],"freeResult":{"freeInfo":{"scatter":2,"idxs":[1,4,5,9,12,14],"addMult":1,"freeCnt":6},"triFreeCnt":1},"c":44,"code":200,"zjLuXian":[],"betcoin":50000,"wincoin":51283200,"spEffect":{"wincoin":51283200,"kind":5},"addMult":1,"mults":[10000,20000,30000,40000,50000,60000,70000,80000,90000,100000,120000,140000,160000,180000,200000,220000,240000,260000,280000,300000,320000,340000,360000,400000,500000],"booms":{"idx":0,"pool":[50000,100000,200000,300000,400000,500000,600000,700000,750000,900000,1000000,1100000,1250000,1500000,1750000,2500000],"indexs":[]},"coin":1101450600,"spLuXian":0,"select":{"state":false},"spcode":200,"collect":{"bet":0,"num":79,"coin":1350000,"free":10,"open":0,"min":3,"cnum":27,"idx":2,"total":200},"allFreeCnt":6,"nextBetLine":{"spcode":500},"pooljp":0,"lastBetCoin":1101450600,"scatterZJLuXian":{"mult":0,"coin":0,"indexs":[]},"pool":{"info":[{"idx":4,"coin":24717700},{"idx":5,"coin":469800},{"idx":9,"coin":502600},{"idx":12,"coin":25593100}],"total":51283200},"freeWinCoin":51283200,"subGameInfo":{"subGamid":-1,"isMustJoin":-1},"freeCnt":6}
        if(msg.code == 200){
            this._super(msg);
            this._collectData = msg.collect;
            this._selectData = msg.select;
            this._boomsData = this._deskInfo.booms;
        }
    },

    //获取booms
    getBoomsData(){
        return this._boomsData;
    },

    //获取select数据
    getSelectData(){
        return this._selectData;
    },

    SetSubGameData:function(data){
        this._subGame = data
    },

    GetSubGameData:function(){
        return this._subGame
    },

    //是否选择了wheel结果
    IsSelectWheel:function(){
        return this._deskInfo.select
    },

    
    //获取游戏数据
    getGameInfo(){
        return this._gameInfo;
    },

    //获取收集数据
    getCollectData(){
        return this._collectData;
    },
    //设置收集数据中的已收集能量
    setCollectDataNum(num){
        this._collectData.num = num;
    },

    //清除收集数据
    clearCollectData(){
        let gameinfo = this.getGameDataInfo();
        if(gameinfo.collect){
            gameinfo.collect.open = 0;
        }
    },
    //清除免费数据
    clearFreeData(){
        this._gameInfo.allFreeCnt = 0;
    },

    isOpenCollectProgress: function () {
        return this.GetBetIdx() >= this.needBet;
    },

    //将免费中奖池赢取的coin合并到免费总赢中
    setFreeWinTotal(wincoin){
        this._gameInfo.freeWinCoin = wincoin;
    },

    //是否免费结束
    isNormalFreeGameOver(){
        return this._gameInfo.freeCnt==0&&this._gameInfo.allFreeCnt > 0;
    },
    //获取免费数据
    getGameDataInfo(){
        let gamedata = cc.vv.gameData.getGameInfo();
        if(gamedata)
            return gamedata;
        gamedata = cc.vv.gameData.getDeskInfo();
        if(gamedata)
            return gamedata;
        return null;
    },

    //是否是大关卡
    isBigGate:function(idx){
        let res = false;
        for(let i = 0; i < BigGate.length; i++){
            if(idx == BigGate[i]){
                res = true
            }
        }
        return res
    },
    //是否触发普通免费
    isTriggerNormalFree: function(){
        return (this._gameInfo.freeResult.freeInfo&&this._gameInfo.freeResult.freeInfo.freeCnt);
    },
    //是否进入能量游戏
    isEnterEnergyGame(){
        if(this._collectData&&this._collectData.open > 0&&this._selectData.state)
            return true;
        return false;
    },
    //是否在免费游戏中
    isFreeGamesTime: function () {
        return this._deskInfo.allFreeCount > 0;
    },
    //按节点播放spine
    playSpine:function(node,aniName,loop,endCall){
        if(node){
            node.active = true
            let ske = node.getComponent(sp.Skeleton)
            if(ske){
                ske.setAnimation(0,aniName,loop)
                ske.setCompleteListener(() => {
                    if(endCall){
                        endCall()
                    }
                })
            }
        }
        
    },

    //是否免费中
    isFreeTime:function(){
        let gameinfo = this.getGameDataInfo();
        if(gameinfo.freeCnt > 0)
            return true;
        return false;
    },

    //是否进入免费
    isEnterFreeGame:function(){
        let gameinfo = this.getGameDataInfo();
        if(gameinfo.booms&&gameinfo.freeCnt == gameinfo.allFreeCnt&&gameinfo.allFreeCnt > 0){
           return true;
        }
        return false;
    },

    //是否等待操作中
    isWaitOperate(){
        return this._isWait;
    },

    //设置等待操作
    setWaitOperate(iswait){
        this._isWait = iswait;
    },

    //是否旋转中
    isReelMove(){
        if(this.GetFreeTime()>0)
            return true;
        return this._isReelMove||this._autoTime>0;
    },

    //设置reel移动中
    setReelMove(ismove){
        this._isReelMove = ismove;
    },

    //保存免费脚本
    saveFreeGameScript(freescript){
        this._freeGameScript = freescript;
    },

    //获取免费脚本
    getFreeGameScript(){
        return this._freeGameScript;
    },

});
