
/**
 * 墨西哥帅哥游slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _isFireGame:true,
        _scatterCount:0,
    },

    //重写
    RegisterEvent:function(){
        if(!this._energyfreegame){
            this._energyfreegame = cc.find('Canvas/safe_node/node_energy_free_game').getComponent('LuckyCat_Energy_FreeGame');
        }

    },


    //重写
    StartMove:function(){
        this._super()
        cc.vv.gameData.setReelMove(true);
        this._energyfreegame.playMidAniClose();
        Global.SlotsSoundMgr.playNormalBgm()

        //游戏开始不能进地图
        cc.find("Canvas/safe_node/node_energy/btn_juanzhou").getComponent(cc.Button).interactable = false;
    },

    //自己游戏构造bonus数据
    GetBonusData:function(idx){
        let bonusData = this._gameInfo.bonusGame
        if(bonusData && bonusData.open){
            for(let i = 0; i < bonusData.coins.length; i++){
                if(bonusData.coins[i].idx == idx){
                    return {t:"coin",num:bonusData.coins[i].num}
                }
            }
    
            for(let i = 0; i < bonusData.free.length; i++){
                if(bonusData.free[i].idx == idx){
                    return {t:"free",num:bonusData.free[i].num}
                }
            }
        }
        

    },

    SetSlotsResult:function(cards){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {}
                res.sid = cards[i]
                res.data = this.GetBonusData(i+1)
                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
            
        }
        for(let j = 0; j < this._reels.length; j++){
            let item = this._reels[j]
            let reelRes = reelResults[j]
            item.SetResult(reelRes)
        }
    },

    showScatterCoin(colidx){
        let gameinfo = cc.vv.gameData.getGameInfo();
        if(gameinfo.booms){
            //如果是免费中
            let indexinfo = gameinfo.booms.indexs.info;
            if(indexinfo){
                for(let i=0;i<indexinfo.length;i++){
                    let col = (indexinfo[i].idx - 1) % this._col;
                    if(col == colidx){
                        let symbol = this.GetSymbolByIdx(indexinfo[i].idx);
                        symbol.showSymbolNumber(indexinfo[i].coin);
                    }
                }
            }
        }
    },

    //重写：小游戏取的数据不一样
    onMsgSpine:function(msg){
        this._scatterCount = 0;
        //复位wild动画
        this.resetScatterShow();
        this._super(msg);

    },

    //
    //重写显示中奖线路
    ShowWinTrace(){
        this._super();
        if(cc.vv.gameData.isEnterFreeGame()){
            //进入免费
            for(let i = 0; i < 5; i++){
                let sys = this._reels[i]._symbols
                for(let j = 0; j < 3;j++){
                    sys[j].playScatterAnimation();
                }
            }
        }
    },

    //重写单列停止
    OnReelSpinEnd:function(colIdx){
        this.showScatterCoin(colIdx);
        //如果有金币需要播放金币停止音效/还有scatter音效
        this.reelStopPlaySound(colIdx);
        this._super(colIdx);
    },

    //列停止音效播放/同时播放scatter动画
    reelStopPlaySound(colIdx){
        //let defstopsound = 'base/reel_stop';
        let sys = this._reels[colIdx]._symbols
        for(let j = 0; j < 3;j++){
            let itemid = sys[j].GetShowId();
            if(itemid == 2||itemid==3||itemid==4||itemid==5){
                this._scatterCount++;
                if(colIdx < 4){
                    this.showReelBg(colIdx);
                }else{
                    if(this._scatterCount >= 3){
                        this.showReelBg(colIdx);
                    }
                }
            }
        }
        if(colIdx == 4){
            this.hideReelBg();
        }
    },

    //重写停止移动
    StopMove(){
        this._super();
        this.hideReelBg();
    },

    //列停止显示背景
    showReelBg(colIdx){
        let reelindex = colIdx+1;
        let node_ani = cc.find('reels/reel'+reelindex+'/mask/node_anti',this.node);
        node_ani.active = true;
        node_ani.getComponent(sp.Skeleton).setAnimation(0,'animation2',true);
    },

    //隐藏背景动画
    hideReelBg(){
        for(let i=1;i<6;i++){
            let node_ani = cc.find('reels/reel'+i+'/mask/node_anti',this.node);
            node_ani.active = false;
        }
    },

    //关闭scatter动画
    resetScatterShow(){
        for(let i = 0; i < 5; i++){
            let sys = this._reels[i]._symbols
            for(let j = 0; j < 4;j++){
                sys[j].resetScatterShow();
            }
        }
        this.resetWildShow();
    },

    //复位wild显示
    resetWildShow(){
        let parNode = cc.find("top_ani",this.node)
        for(let i = 0; i < 5; i++){
            for(let j = 0; j < 4;j++){
                let showNode = cc.find(cc.js.formatStr("top_symbol_%s_%s",j,i),parNode);
                if(showNode&&showNode.active){
                    showNode.active = false;
                }
            }
        }
    },

    //重写：显示bonus中奖
    async OnSpinEnd () {
        cc.vv.gameData.setReelMove(false);
        //是否中奖,中奖了就不能开始下一局
        let bHit = this.CheckSpecialReward()
        if(bHit){ //所有按钮状态显示成灰太
            this._bottomScript.ShowBtnsByState("moveing_1")
        }

        //是否能收集能量
        if (cc.vv.gameData.isOpenCollectProgress()) {
            this.CollectEnergy();
        }
        await this.stopSpinPlayMulti();
        //显示中奖路线
        this.ShowWinTrace()
        //播放scatter动画
        this.playScatterAnimation(true);
        //显示底部赢钱(免费中不会显示wincoin 移动到中线后)
        await this.playBottomWin();
        //如果进入能量游戏
        await this.enterEnergyGame();
        //检测免费游戏
        await cc.vv.gameData.getFreeGameScript().onRecvPlayLineFinish();
        await this._energyfreegame.playLineOver();
        // await this.awaitTime(0.5);
        //下一局
        this.CanDoNextRound();
        //免费游戏和自动模式不开启地图
        let rest = cc.vv.gameData.GetFreeTime()
        let autoTime = cc.vv.gameData.GetAutoModelTime()
        if (rest == 0 && autoTime <= 0) {
            cc.find("Canvas/safe_node/node_energy/btn_juanzhou").getComponent(cc.Button).interactable = true;
        }
    },

    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },

    //停止旋转后播放倍率显示
    async stopSpinPlayMulti(){
        await this._energyfreegame.spinEnd();
    },

    //播放线完成
    async enterEnergyGame(){
        return new Promise((success)=>{
            if(cc.vv.gameData.isEnterEnergyGame()){
                cc.log('进入能量游戏');
                cc.find('Canvas/safe_node/node_energy').getComponent('LuckyCat_Energy').IsEnterEnergyGame();
            }else{
                success();
            }
        })
    },

    //是否触发小游戏
    CheckTriggerSubGame:function(){
        if(cc.vv.gameData.isEnterEnergyGame())
            return true;
        return false;
    },

    //播放scatter动画
    playScatterAnimation(isplay){
        if(cc.vv.gameData.isTriggerNormalFree()){
            this.Backup();
            //进入免费
            for(let i = 0; i < 5; i++){
                let sys = this._reels[i]._symbols
                for(let j = 0; j < 3;j++){
                    sys[j].playScatterAnimation(isplay);
                }
            }

        }
    },
    
    async playBottomWin () {
        return new Promise((success)=>{
            let nWin = cc.vv.gameData.GetGameWin()
            let nTotal = nWin
            let updateAllCoin = true;
            let gameinfo = cc.vv.gameData.getGameInfo();
            if(gameinfo.freeCnt != gameinfo.allFreeCnt&&gameinfo.allFreeCnt > 0){
                nTotal = cc.vv.gameData.GetGameTotalFreeWin()
                updateAllCoin = false;
            }
            this.ShowBottomWin(nWin,nTotal,updateAllCoin,()=>{
                success();
            });
        });
    },
    //收集能量
    CollectEnergy(){
        if(cc.vv.gameData.isTriggerNormalFree())
            return;
       //显示中奖
       let isupdate = false;
       for(let i = 0; i < 5; i++){
            let sys = this._reels[i]._symbols
            for(let j = 0; j < 3;j++){
                let id = sys[j].GetShowId();
                if((id == 2)||(id == 3)||(id == 4)||(id == 5)){
                    isupdate = true;
                }
                sys[j].PlayCollectAction();
            }
        }

         //移动结束 通知刷新能量
         if(isupdate){
            this.scheduleOnce(()=>{
                //移动结束 通知刷新能量
                Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_REFUSH_ENERGY);
            },1);
         }
    },

    //免费游戏收集金币
    scatterCollectGoldCoin(){
        
    },

    // //重写
    // CheckTriggerSubGame:function(){
    //     return this.bBounusGame
    // },

    //检查是否触发免费
    CheckEnterFreeGame:function(){
        let res = false
        if(this._gameInfo.allFreeCnt>0&&this._gameInfo.freeCnt == this._gameInfo.allFreeCnt){
            return true;
        }
        return res
    },


    //显示bound游戏的入场效果
    ShowReelEffect:function(){
        let self = this

        let role = cc.find("spine_role",this.node)
        role.active = true
        let roleSp = role.getComponent(sp.Skeleton)
        roleSp.setAnimation(0,"animation3",true)
        roleSp.addAnimation(0,"animation2",false,3)
        // roleSp.addAnimation(0,"animation2",true,3) //又恢复正常太，等第一列停止

        let music = cc.find("reels_frame/node_eff/spine_music",this.node)
        music.active = true
        let musicSp = music.getComponent(sp.Skeleton)
        musicSp.setAnimation(0,'animation',false)
        musicSp.setCompleteListener(() => {
            let kuang = cc.find("reels_frame/node_eff/spine_kuang",self.node)
            kuang.active = true
            let kuangSp = kuang.getComponent(sp.Skeleton)
            kuangSp.setAnimation(0,"animation1",false)
            kuangSp.addAnimation(0,"animation2",false)
            kuangSp.addAnimation(0,"animation3",false)
            musicSp.setCompleteListener(null)
        })
        
        
    },
    
    //转场动画
    ShowTranstion:function(pEndCall){
        // let self = this
        let tranNode = cc.find("Canvas/safe_node/translate_node")
        tranNode.active = true
        let ani = tranNode.getComponent(sp.Skeleton)
        ani.setAnimation(0,"animation",false)
        let delayCall = function(){
            if(pEndCall){
                pEndCall()
            }

        }
        this.scheduleOnce(delayCall,0.5)
    },

    ShowTranstionExit:function(){
        let self = this
        let endCall = function(){
            //隐藏wheel
            let node = cc.find("Canvas/safe_node/wheel_node")
            node.active = false
        
        }
        let delayCall = function(){
            let subData = cc.vv.gameData.GetSubGameData()
            if(subData.awardType == 1){
                let add = subData.num
                self.ShowBottomWin(add,add,true)
                self.CanDoNextRound()
            }
            else{
                //免费

            }
        }
        this.scheduleOnce(delayCall,1)
    },

    OnEventWheelResult:function(data){
        let val = data.detail
        let node_pop = cc.find("Canvas/safe_node/node_pop_ui")
        node_pop.active = true
        let cmp = node_pop.getComponent("JalapanDelight_Pop")
        cmp.ShowWheelResult(val)
    },

    //重写
    ReconnectShow:function(){
        //免费是否选择了
        let total = cc.vv.gameData.GetTotalFree()
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest > 0){
            this._bottomScript.ShowFreeModel(true,rest,total)
        }
    }
});
