
/**
 * 能量收集
 */
let UNLOCKVAL = 10000
cc.Class({
    extends: cc.Component,

    properties: {
        _playUnlockState:0, 
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        let btn_lock = cc.find('btn_lock',this.node)
        Global.btnClickEvent(btn_lock,this.onClicklock,this)

        let btn_juanzhou = cc.find('btn_juanzhou',this.node)
        Global.btnClickEvent(btn_juanzhou,this.onClickJuanzhou,this)
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventChangeBetIdx,this)
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_REFUSH_ENERGY,this.onEventRefushEnergy,this)
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_GAME_START, this.onRecvStart, this);
        this._soundCfg = cc.vv.gameData.getGameCfg().soundCfg;
    },

    start () {
        this.initShow();
    },

    //初始化显示
    initShow:function(){
        //当前押注是否足够解锁
        let collectData = cc.vv.gameData.getCollectData();
        if(!collectData)
            return;

        //解锁节点的显示/隐藏
        this.UNLOCKVAL = collectData.min
        let betIdx = cc.vv.gameData.GetBetIdx()
        let btn_lock = cc.find('btn_lock',this.node)
        let ani_node = btn_lock.getChildByName('node_spine')
        this.updateCoinProgress(collectData)
        
        if(betIdx >= this.UNLOCKVAL){
            //解锁
            if(this._playUnlockState != 1){
                this._playUnlockState = 1
                btn_lock.active = true
                Global.playHSEffect('unlock');
                cc.vv.gameData.playSpine(ani_node,'animation2',false,()=>{
                    btn_lock.active = false;
                 })
            }
        }
        else{
            //锁定
            if(this._playUnlockState != 2){
                this._playUnlockState = 2
                btn_lock.active = true
                Global.playHSEffect('lock');
                cc.vv.gameData.playSpine(ani_node,'animation1',false,()=>{
                 }) 
            }
        }

        //初始化刷新能量值
        this.updateEnergyGame(collectData,1.2,true);
        //更新下一动画图标
        this.updateNextAimIcon(collectData);
    },

    //点击解锁
    onClicklock:function(){
        if(cc.vv.gameData.isReelMove())
            return;
        if(this._playUnlockState == 1)
            return;
        //更新押注额
        cc.vv.gameData.GetBottomScript().SetBetIdx(this.UNLOCKVAL)
        //然后播放解锁表现
        let btn_lock = cc.find('btn_lock',this.node)
        let ani_node = btn_lock.getChildByName('node_spine')
        cc.vv.gameData.playSpine(ani_node,'animation2',false,()=>{
            btn_lock.active = false;
            this._playUnlockAni = false;
         })
        
    },

    //点击卷轴
    onClickJuanzhou:function(){
        if(cc.vv.gameData.isReelMove())
            return;
        Global.playHSEffect('bonus_dialog_click');
        let node = cc.find('Canvas/safe_node/map_game')
        node.active = true
        node.getComponent('LuckyCat_Map').enterMap(false)
    },

    onEventChangeBetIdx:function(){
        this.initShow()
    },

    updateCoinProgress:function(collectData){
        if(collectData){
            this._collectcoin = collectData.num;
            let per = collectData.num/collectData.total
            this.showEnergyProgress(per);
            if(per > 0){
                let pro_spin = cc.find('masknode/coin_progress/bar/spin_pro',this.node)
                this._playNodeSpine(pro_spin,'animation',true)
            }
        }
    },
    showEnergyProgress:function(per){
        let pro = cc.find('masknode/coin_progress',this.node)
        pro.getComponent(cc.ProgressBar).progress = per
        this.playProgressChangeSp(pro,per);
    },

    onEventRefushEnergy:function(){
        console.log("刷新能量");
        let collectData = cc.vv.gameData.getCollectData();
        if(this._collectcoin == collectData.num)
            return;
        
        //金币撞击动画
        let coin_collect = cc.find('spr_left/spin_collect',this.node)
        this._playNodeSpine(coin_collect,'animation',false)
        //进度条动画
        this.updateCoinProgress(collectData);  
    },

    //进入能量游戏判断
    IsEnterEnergyGame(){
        let collectData = cc.vv.gameData.getCollectData();
        this.updateEnergyGame(collectData,2,false);
    },

    //刷新下一个目标图标
    updateNextAimIcon(collectData){
        //更新下一个目标图标
        let bigGate = {2:'theme160_collect_house1',7:'theme160_collect_house2',13:'theme160_collect_house3',20:'theme160_collect_house4'};
        let curMapIdx = collectData.idx
        let fileName = bigGate[curMapIdx+1]
        let spr_next = cc.find('spr_yb',this.node)
        if(!fileName){
            cc.loader.loadRes('games/LuckyCat/images/plist/map',cc.SpriteAtlas,(err,data) => {
                spr_next.getComponent(cc.Sprite).spriteFrame = data.getSpriteFrame('theme160_map_sushi_light')
            })
        }else{
            cc.loader.loadRes('games/LuckyCat/images/plist/base',cc.SpriteAtlas,(err,data) => {
                spr_next.getComponent(cc.Sprite).spriteFrame = data.getSpriteFrame(fileName)
            })
        }
    },

    //进入能量小游戏
    updateEnergyGame(collectData,delay,isinit){
        let selectdata = cc.vv.gameData.getSelectData();
        if(selectdata&&selectdata.state&&collectData.open > 0){
            cc.vv.gameData.GetBottomScript().ShowBtnsByState('moveing_1');
            this.scheduleOnce(()=>{
                let node = cc.find('Canvas/safe_node/map_game')
                node.active = true
                node.getComponent('LuckyCat_Map').enterMap(true)
            },delay)
        }else{
            //大关免费游戏会发送collect数据 此处可能有问题
            if(collectData&&collectData.open == 2&&isinit){
                cc.find('Canvas/safe_node/node_energy_free_game').getComponent('LuckyCat_Energy_FreeGame').reconnectEnterFreeGame();
            }
        } 
    },

    //能量大关/小关游戏结束
    onEnergyGameOver:function(){
        this.showEnergyProgress(0);
        cc.vv.gameData.setCollectDataNum(0)//设置已收集能量为0
        let collectdata = cc.vv.gameData.getCollectData();
        if(collectdata){
            this.updateNextAimIcon(collectdata);
        }
    },

    //进度条改变 播放特效
    playProgressChangeSp(pro,per){
        if(per >= 1){
            Global.playHSEffect('full');
            //播放能量满效果
            let fullnode = cc.find('progressfull',pro);
            cc.vv.gameData.playSpine(fullnode,'animation',false,()=>{
                fullnode.active = false;
            })
        }else{
            Global.playHSEffect('symbol_fly');
            let jieshounode = cc.find('bar/jieshou',pro);
            let pronode = cc.find('bar/progress',pro);
            cc.vv.gameData.playSpine(jieshounode,'animation',false);
            cc.vv.gameData.playSpine(pronode,'animation',false);
        }
    },

    onRecvStart:function(){
        //新的一局
        this._newRound = true
    },
    
    _playNodeSpine:function(node,aniName,loop){
        let ske = sp.Skeleton
        if(node){
            node.active = true
            let sp = node.getComponent(ske)
            sp.setAnimation(0,aniName,loop)
            if(!loop){

            }
        }
    }

    // update (dt) {},
});
