/**
 * 地图
 */

cc.Class({
    extends: cc.Component,

    properties: {
        yb_grey:cc.SpriteFrame,
        yb_light:cc.SpriteFrame,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._node_head = cc.find('spr_head',this.node)
        this._node_mask = cc.find('node_mask',this.node)
        this._head_pos = cc.find('head_pos',this.node)
        
        let btnBack = cc.find('spr_mid/spr_foot/btn_back',this._node_mask)
        Global.btnClickEvent(btnBack,this.onClickBack,this)

        this._soundCfg = cc.vv.gameData.getGameCfg().soundCfg;
    },

    start () {

    },

    showMapDetail:function(){
        let self = this

        let engData = cc.vv.gameData.getCollectData();
        let curMapId = engData.idx
        let yuanbaolight = cc.find('spr_mid/yuanbaolight',this._node_mask)
        yuanbaolight.active = false;

        for(let i = 1; i < 21; i++){
            let item = cc.find('spr_mid/s_'+i,this._node_mask)
            if(item){       
                if(cc.vv.gameData.isBigGate(i)){
                    if(i > curMapId){
                        item.getComponent(sp.Skeleton).setAnimation(0,'animation1_3',true);
                    }else{
                        if(i == curMapId&&!this._bTrigger){
                            item.getComponent(sp.Skeleton).setAnimation(0,'animation1_1',true);
                        }
                    }
                }else{
                    if(i < curMapId){
                        //点亮
                        if(this._bTrigger){
                         Global.playHSEffect(this._soundCfg.map_move);   
                        }
                        item.getComponent(cc.Sprite).spriteFrame = this.yb_light
                    }
                    else if(i == curMapId){
                        //播放动画
                        this.initShowSmallGate(item,yuanbaolight);
                        item.getComponent(cc.Sprite).spriteFrame = this.yb_light
                        if(this._bTrigger){
                          Global.playHSEffect(this._soundCfg.map_move);  
                        }
                    }
                    else{
                        //灰色
                        item.getComponent(cc.Sprite).spriteFrame = this.yb_grey
                    }
                }
            }  
        }

         //线路动画播放
         let node_lx = cc.find('spr_mid/node_lx',this._node_mask)
         node_lx.active = curMapId > 1

        if(curMapId>1){
            let mapindex = curMapId - 1;
            let lxAni = cc.js.formatStr('animation%s_%s',mapindex,mapindex)
            if(this._bTrigger){
                Global.playHSEffect('map_node');
                lxAni = cc.js.formatStr('animation%s',mapindex);
            }
            // Global.playHSEffect('map_move');
            cc.vv.gameData.playSpine(node_lx,lxAni,false,()=>{
                let item = cc.find('spr_mid/s_'+curMapId,this._node_mask)
                if(cc.vv.gameData.isBigGate(curMapId)){
                    //开启大关卡
                    Global.playHSEffect('map_node');
                    this.openBigGate(item);
                }else{
                    //开启小关卡
                    this.openSmallGate(item,yuanbaolight);
                }
            })
        }
        if(this._bTrigger){
            this.scheduleOnce(()=>{
                this.existMap(this.showSubGame);
            },2)
        }
    },

    delayShowExistMap:function(){
        if(this._bTrigger){
            let delayCall = function(){
                this.existMap(this.showSubGame(this))
            }
            this.scheduleOnce(delayCall,2)
        }
    },

    //进入
    enterMap:function(bTrigger){
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
        let self = this
        this._bTrigger = bTrigger
        
        this._node_head.position = cc.v2(0,800)
        let endPos = this._head_pos.position
        this._node_head.active = true
        cc.tween(this._node_head)
        .to(0.3,{position:cc.v2(endPos.x,endPos.y)})
        .call(() => {
            Global.playHSEffect('map_close');
            self._node_mask.active = true
            let sprMid = cc.find('spr_mid',self._node_mask)
            sprMid.active = true
            sprMid.position = cc.v2(0,1000) 
            cc.tween(sprMid)
            .to(0.3,{position:cc.v2(0,0)})
            .call(() => {
                self.showMapDetail()

                //back game 按钮放大一下
                let btnBack = cc.find('spr_foot/btn_back',sprMid)
                btnBack.active = !self._bTrigger
                cc.tween(btnBack)
                .to(0.2,{scale:1.3})
                .to(0.2,{scale:1})
                .call(() => {
                    
                }).start()
            })
            .start()
        })
        .start()

    },

    //退出
    existMap:function(endCall){
        let self = this
        let sprMid = cc.find('spr_mid',self._node_mask)
        cc.tween(sprMid)
        .to(0.3,{position:cc.v2(0,1000)})
        .call(() => {
            Global.playHSEffect('map_open');
            self._node_mask.active = false
            cc.tween(self._node_head)
            .to(0.3,{position:cc.v2(0,800)})
            .call(() => {
                if(endCall){
                    endCall()
                }
                self.node.active = false
            })
            .start()
        })
        .start()
    },

    onClickBack:function(){
        Global.playHSEffect('bonus_dialog_click');
        this.existMap(()=>{
            this.node.active = false;
            cc.vv.gameData.GetBottomScript().ShowBtnsByState('idle');
        })
    },

    //直接打开显示当前小关卡
    initShowSmallGate(itemnode,yuanbaonode){
        yuanbaonode.position = yuanbaonode.parent.convertToNodeSpaceAR(itemnode.convertToWorldSpaceAR(cc.v2(0,0)));
        yuanbaonode.active = true;
        //开始播放动作
        let ybsp = yuanbaonode.getComponent(sp.Skeleton)
        ybsp.setAnimation(0,'animation2',true)
    },

    //开启大关卡
    openBigGate(itemnode){
        let ybsp = itemnode.getComponent(sp.Skeleton)
        if(this._bTrigger){
            ybsp.setAnimation(0,'animation1_2',false)
            ybsp.setCompleteListener(() => {
                ybsp.setAnimation(0,"animation1_4",false)
                ybsp.setCompleteListener(null)
            })
        }
    },

    //开启小关卡
    openSmallGate(itemnode,yuanbaonode){
        itemnode.getComponent(cc.Sprite).spriteFrame = this.yb_light;
        yuanbaonode.position = yuanbaonode.parent.convertToNodeSpaceAR(itemnode.convertToWorldSpaceAR(cc.v2(0,0)));
        yuanbaonode.active = true;

        //开始播放动作
        let ybsp = yuanbaonode.getComponent(sp.Skeleton)
        ybsp.setAnimation(0,'animation1',false)
        ybsp.setCompleteListener(() => {
            ybsp.setAnimation(0,"animation2",true)
            ybsp.setCompleteListener(null)
        })
    },

    showSubGame:function(){
        let engData = cc.vv.gameData.getCollectData();
        if(engData == undefined)
            return;
        let opengame = engData.open;
        console.log("显示子游戏:"+opengame);
        if(opengame == 2){
            //中免费
             let freeGame = cc.find('Canvas/safe_node/node_energy_free_game')
             freeGame.active = true;
             let scp = freeGame.getComponent('LuckyCat_Energy_FreeGame');
             scp.energyFreeGameStart(engData)

        }
        else if(opengame == 1){
            //中777
            let mapGame = cc.find('Canvas/safe_node/LMSlots_Subgame777')
            mapGame.getComponent('LMSlots_Subgame777').showEnter(engData.bet);
        }
        cc.vv.gameData.clearCollectData();
        if(opengame > 0){
            cc.find('Canvas/safe_node/node_energy').getComponent('LuckyCat_Energy').onEnergyGameOver();
        }
    }

    // update (dt) {},
});
