

cc.Class({
    extends: cc.Component,

    properties: {
        _bgs: null,
        freegamespine:cc.Node,
    },

    init(bgs) {
        this._bgs = bgs;
        this._upCount = 0;
        this._freeGameNode = cc.find("safe_node/free_game",this.node);
        this._freeBgNode = cc.find("safe_node/Normal/free_bg",this.node);
        if(this._freeBgNode) this._freeBgNode.active = false;
        if(this._freeGameNode) this._freeGameNode.active = false;
        this._freeGameOverTips = cc.find("safe_node/free_game_over",this.node);
        if(this._freeGameOverTips) this._freeGameOverTips.active = false;
    },

    onLoad(){
        this._soundCfg = cc.vv.gameData.getGameCfg().soundCfg;
        this._freedialogui = cc.find("safe_node/node_free_game",this.node);
        for(let i=1;i<4;i++){
            let btn_bag = cc.find('nodeui/nicewin/item'+i,this._freedialogui)
            Global.btnClickEvent(btn_bag,this.choiceMoneybagEvent,this)
        }
        let btn1 = cc.find('nodeui/youwin/startgame/btn_start',this._freedialogui)
        Global.btnClickEvent(btn1,this.youwinStartEvent,this)

        let btn2 = cc.find('nodeui/youwin/settlementgame/btn_collect',this._freedialogui)
        Global.btnClickEvent(btn2,this.youwinCollectEvent,this)

        this.init();
        this.reConnectDo()
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.OnRecvMsgSubAction, this);
    },
    start() {

    },
    onDestroy(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.OnRecvMsgSubAction,this);
    },

    //断线重连的恢复检查
    reConnectDo(){
        let datainfo = cc.vv.gameData.getGameDataInfo();
         if(datainfo.booms){
            cc.find("kuang_xz",this._freeGameNode).active = false;
            this.initPoolNum(datainfo);
            this.showFreeUI(true);
            if(datainfo.select&&datainfo.select.state&&datainfo.select.rtype == 3){
                this.showBoomsSelect();
            }else{
                if(cc.vv.gameData.isEnterEnergyGame()){
                    cc.find('Canvas/safe_node/node_energy').getComponent('LuckyCat_Energy').IsEnterEnergyGame();
                }else{
                    this.scheduleOnce(() => {
                        cc.vv.gameData.GetBottomScript().CanDoNextRound();
                    }, 0.5);
                }
            }
         }
    },

    //手动旋转
    handSpine(){
        console.log("####手动旋转");
        this.scheduleOnce(()=>{
            cc.vv.gameData.GetBottomScript().CanDoNextRound();
        },1);
    },

    //初始话数值
    initPoolNum(datainfo){
        this._upCount = 0;
        this.resetGrayTopShow();
        if(datainfo.booms){
            let poolnum = datainfo.booms.pool;
            for(let i=0;i<poolnum.length;i++){
                let shownum = cc.find("topshow/topshow"+(i+1)+"/shownum",this._freeGameNode);
                shownum.getComponent(cc.Label).string = Global.FormatNumToComma(poolnum[i]);
            }

            //设置当前跳转层级
            this._upCount = datainfo.booms.idx;
            this.initUpIndex(datainfo.booms.idx);
        }
    },

    //显示select
    showBoomsSelect(){
        //显示选择界面
        this._stopCounttime = false;
        this._nextTime = 5;
        this.showNiceWinUI();
        this.showDiscountTime();
        this.choiceMoneyBagButtonShow(true);
    },

    //显示倒计时
    showDiscountTime:function(){
        if(this._stopCounttime)
            return;
        let lblTime = cc.find("nodeui/nicewin/timebg/counttime",this._freedialogui)
        lblTime.getComponent(cc.Label).string = this._nextTime
        if(this._nextTime <= 0){
            this.unschedule(this.showDiscountTime,this)
            this.choiceMoneyBagButtonShow(false);
            this.sendChoiceMoneybag(Global.random(1,3));
            this._stopCounttime = true;
        }else{
            this.scheduleOnce(()=>{
                this.showDiscountTime();
            },1)
        }
        --this._nextTime
    },

    //显示钱袋子音效
    showNiceWinUI(){
        Global.playHSEffect(this._soundCfg.full);
        this._freedialogui.active = true;
        cc.find("nodeui/nicewin",this._freedialogui).active = true;
        cc.find("nodeui/youwin",this._freedialogui).active = false;

        for(let i=1;i<4;i++){
            let btn_bag = cc.find('nodeui/nicewin/item'+i+'/spine_bag',this._freedialogui)
            btn_bag.getComponent(sp.Skeleton).setAnimation(0,'animation1',true);

            let bg = cc.find('nodeui/nicewin/item'+i+'/bg',this._freedialogui);
            bg.active = false;
        }
    },

    //显示youwin界面 type 0开始 1结束
    showYouWinUI(type,freecnt){
        Global.SlotsSoundMgr.stopBgm();
        cc.vv.gameData.setWaitOperate(true);
        this._freedialogui.active = true;
        cc.find("nodeui/nicewin",this._freedialogui).active = false;
        let youwinnode = cc.find("nodeui/youwin",this._freedialogui);
        youwinnode.active = true;
        youwinnode.scale = 0;
        if(type == 0){
            Global.playHSEffect(this._soundCfg.free_dialog_start_show);
            cc.find("nodeui/youwin/startgame",this._freedialogui).active = true;
            cc.find("nodeui/youwin/settlementgame",this._freedialogui).active = false;
            cc.find("nodeui/youwin/startgame/freetime",this._freedialogui).getComponent(cc.Label).string = freecnt;
            cc.tween(youwinnode).to(0.3,{scale:1},{easing:'backOut'}).start();

            let btn1 = cc.find('nodeui/youwin/startgame/btn_start',this._freedialogui)
            cc.vv.gameData.checkAutoPlay(btn1, ()=>{
                Global.playHSEffect(this._soundCfg.common_click);
                let youwinnode = cc.find("nodeui/youwin",this._freedialogui);
                cc.tween(youwinnode).to(0.3,{scale:0},{easing:'backInOut'}).call(()=>{
                    this._freedialogui.active = false;
                    Global.playHSEffect(this._soundCfg.transition_free);
                    cc.vv.gameData.playSpine(this.freegamespine,'animation',false,()=>{
                        Global.SlotsSoundMgr.playBgm(this._soundCfg.free_bgm);
                        this.handSpine();
                    })
                    this.scheduleOnce(() => {
                        let datainfo = cc.vv.gameData.getGameDataInfo();
                        cc.find("kuang_xz",this._freeGameNode).active = false;
                        this.initPoolNum(datainfo);
                        this.showFreeUI(true);
                    }, 0.3);
                }).start();
            })
        }else{
            Global.playHSEffect(this._soundCfg.free_dialog_collect_show);
            cc.find("nodeui/youwin/startgame",this._freedialogui).active = false;
            cc.find("nodeui/youwin/settlementgame",this._freedialogui).active = true;
            let collect = cc.find("nodeui/youwin/settlementgame/collectnum",this._freedialogui);
            let wincoin = cc.vv.gameData.GetGameTotalFreeWin();
            cc.tween(youwinnode).to(0.3,{scale:1},{easing:'backOut'}).call(()=>{
                Global.doRoallNumEff(collect,0,wincoin,1,null,null,0,true)
            }).start();
            let btn2 = cc.find('nodeui/youwin/settlementgame/btn_collect',this._freedialogui)
            cc.vv.gameData.checkAutoPlay(btn2, ()=>{
                let self = this
                Global.playHSEffect(this._soundCfg.free_dialog_click);
                let youwinnode = cc.find("nodeui/youwin",this._freedialogui);
                cc.tween(youwinnode)
                    .to(0.3,{scale:0},{easing:'backInOut'})
                    .call(()=>{
                        self._freedialogui.active = false;
                        Global.playHSEffect(self._soundCfg.transition_free);
                        cc.vv.gameData.playSpine(self.freegamespine,'animation',false,()=>{
                            Global.SlotsSoundMgr.playBgm(self._soundCfg.base_bgm);
                            self._freeGameNode.active = false;
                            self.showFreeUI(false);
                            cc.vv.gameData.setWaitOperate(false);
                            cc.vv.gameData.GetTopScript().SetBackLobby(true);
                            let freewin = cc.vv.gameData.GetGameTotalFreeWin();
                            cc.vv.gameData.GetSlotsScript().Resume();
                            // cc.vv.gameData.GetSlotsScript().ShowBottomWin(freewin,freewin,true,()=>{
                            //     if(this._nextpromise){
                            //         this._nextpromise();
                            //         this._nextpromise = null;
                            //     }
                            // });
                            let nVal = cc.vv.gameData.GetCoin()
                            let datainfo = cc.vv.gameData.getGameDataInfo();
                            if(datainfo.select.state){
                                cc.vv.gameData.AddCoin(freewin)
                            }
                            cc.vv.gameData.GetSlotsScript().ShowBottomWin(freewin,freewin,false,()=>{
                                // let nVal = cc.vv.gameData.GetCoin()
                                cc.vv.gameData.GetTopScript().ShowCoin()
                                cc.vv.gameData.GetSlotsScript().CanDoNextRound();
                            });

                        })
                    })
                    .start();
            })
        }
    },

    choiceMoneyBagButtonShow(interactable){
        for(let i=1;i<4;i++){
            let btn_bag = cc.find('nodeui/nicewin/item'+i,this._freedialogui)
            btn_bag.getComponent(cc.Button).interactable = interactable;
        }
    },

    //选中钱袋
    choiceMoneybagEvent(btn){
        console.log("点击按钮:"+btn.node.name);
        let idx = parseInt(btn.node.name.substr(-1,1));
        this.choiceMoneyBagButtonShow(false);
        this.sendChoiceMoneybag(idx);
        this._stopCounttime = true;
    },

    //发送旋转钱袋
    sendChoiceMoneybag(idx){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.data = {}
        req.data.rtype = 3
        req.data.idx = idx;
        req.gameid = cc.vv.gameData.getGameId()
        cc.vv.NetManager.send(req,true);
        Global.playHSEffect(this._soundCfg.free_dialog_pick);
    },

    //图片灰度处理
    changeSpriteGray(sp,isgray){
        var newMaterial = null;
        if(isgray) //置灰
        {
            newMaterial = cc.Material.createWithBuiltin(cc.Material.BUILTIN_NAME.GRAY_SPRITE, 0);
        }
        else  //普通图像
        {
            newMaterial = cc.Material.createWithBuiltin(cc.Material.BUILTIN_NAME.SPRITE, 0);
        }
        newMaterial.define("USE_TEXTURE", true, 0);
        sp.setMaterial(0, newMaterial); //给精灵添加新材质
    },

    //改变数字图片
    changeNumSprite(sp,spname){
        cc.loader.loadRes('games/LuckyCat/images/plist/free_popup',cc.SpriteAtlas,(err,data) => {
            sp.getComponent(cc.Sprite).spriteFrame = data.getSpriteFrame(spname)
         })
    },

    //图集内数字图片名(1 2 3)
    getAtlasSpriteName(num){
        switch (num) {
            case 1:return 'theme160_freePop_4';
            case 2:return 'theme160_freePop_5';
            case 3:return 'theme160_freePop_6';
        }
    },

    //youwin选中开始
    youwinStartEvent(){
        let btn1 = cc.find('nodeui/youwin/startgame/btn_start',this._freedialogui)
        btn1.stopAllActions();
        Global.playHSEffect(this._soundCfg.common_click);
        let youwinnode = cc.find("nodeui/youwin",this._freedialogui);
        cc.tween(youwinnode).to(0.3,{scale:0},{easing:'backInOut'}).call(()=>{
            this._freedialogui.active = false;
            Global.playHSEffect(this._soundCfg.transition_free);
            cc.vv.gameData.playSpine(this.freegamespine,'animation',false,()=>{
                Global.SlotsSoundMgr.playBgm(this._soundCfg.free_bgm);
                this.handSpine();
            })
            this.scheduleOnce(() => {
                let datainfo = cc.vv.gameData.getGameDataInfo();
                cc.find("kuang_xz",this._freeGameNode).active = false;
                this.initPoolNum(datainfo);
                this.showFreeUI(true);
            }, 0.3);
        }).start(); 
    },

    //youwin选中收集
    async youwinCollectEvent(){
        let btn2 = cc.find('nodeui/youwin/settlementgame/btn_collect',this._freedialogui)
        btn2.stopAllActions();
        let self = this
        Global.playHSEffect(this._soundCfg.free_dialog_click);
        let youwinnode = cc.find("nodeui/youwin",this._freedialogui);
        cc.tween(youwinnode)
        .to(0.3,{scale:0},{easing:'backInOut'})
        .call(()=>{
            self._freedialogui.active = false;
            Global.playHSEffect(self._soundCfg.transition_free);
            cc.vv.gameData.playSpine(self.freegamespine,'animation',false,()=>{
                Global.SlotsSoundMgr.playBgm(self._soundCfg.base_bgm);
                self._freeGameNode.active = false;
                self.showFreeUI(false);
                cc.vv.gameData.setWaitOperate(false);
                cc.vv.gameData.GetTopScript().SetBackLobby(true);
                let freewin = cc.vv.gameData.GetGameTotalFreeWin();
                cc.vv.gameData.GetSlotsScript().Resume();
                // cc.vv.gameData.GetSlotsScript().ShowBottomWin(freewin,freewin,true,()=>{
                //     if(this._nextpromise){
                //         this._nextpromise();
                //         this._nextpromise = null;
                //     }
                // });
                let nVal = cc.vv.gameData.GetCoin()
                let datainfo = cc.vv.gameData.getGameDataInfo();
                if(datainfo.select.state){
                    cc.vv.gameData.AddCoin(freewin)
                }
                cc.vv.gameData.GetSlotsScript().ShowBottomWin(freewin,freewin,false,()=>{
                    // let nVal = cc.vv.gameData.GetCoin()
                    cc.vv.gameData.GetTopScript().ShowCoin()
                    cc.vv.gameData.GetSlotsScript().CanDoNextRound();
                });

            })
        })
        .start();
    },

    showFreeUI(isshow){
        this._freeGameNode.active = isshow;
        if(isshow){
            //初始展示免费次数
            let totalfree = cc.vv.gameData.GetTotalFree();
            let resttimes = cc.vv.gameData.GetFreeTime();
            cc.vv.gameData.GetBottomScript().ShowFreeModel(true,totalfree-resttimes,totalfree);
        }else{
            cc.vv.gameData.GetBottomScript().ShowFreeModel(false)
        }

    },

    OnRecvMsgSubAction(msg){
        let self=this
        if(msg.code == 200){
            if(msg.data.rtype != 3)
                return;
            let index = msg.data.idx;
            if(index == undefined){
                console.log('idx数据错误!');
                this._freedialogui.active = false;
                return;
            }
            let btn_bag = cc.find('nodeui/nicewin/item'+index+'/spine_bag',this._freedialogui)
            btn_bag.getComponent(sp.Skeleton).setAnimation(0,'animation2',false);

            let bg = cc.find('nodeui/nicewin/item'+index+'/bg',this._freedialogui);
            bg.active = true;

            let spnum = cc.find('num',bg).getComponent(cc.Sprite);
            this.changeNumSprite(spnum,this.getAtlasSpriteName(msg.data.num));
            //复原sprite
            this.changeSpriteGray(bg.getComponent(cc.Sprite),false);
            this.changeSpriteGray(spnum,false);

            this.scheduleOnce(()=>{
                switch (index) {
                    case 1:
                        this.randomShowIndex([2,3],msg.data.num);
                    break;
                    case 2:
                        this.randomShowIndex([1,3],msg.data.num);
                    break;
                    case 3:
                        this.randomShowIndex([1,2],msg.data.num);
                    break;
                }
                Global.playHSEffect(this._soundCfg.free_dialog_pick_show);
            },1);
            //如果是最后一局选中钱袋 需要修改免费赢取的总coin
            if(msg.data.freeWinCoin){
                cc.vv.gameData.setFreeWinTotal(msg.data.freeWinCoin);
            }
            this.scheduleOnce(()=>{
                this._freedialogui.active = false;
                this.scatterCollectGoldCoin(msg.data.num);
            },2);
        }
    },

    //免费中scatter图标收集金币
    scatterCollectGoldCoin(index){
        //播放收集效果
        this.playGetCoinUp(index);
    },

    randomShowIndex(index,num){
        if(num == 1){
            this.randomShowNum(index[0],2);
            this.randomShowNum(index[1],3);
        }else if(num == 2){
            this.randomShowNum(index[0],1);
            this.randomShowNum(index[1],3);
        }else if(num == 3){
            this.randomShowNum(index[0],1);
            this.randomShowNum(index[1],2);
        }
    },

    randomShowNum(index,num){
        let spine_bag = cc.find('nodeui/nicewin/item'+index+'/spine_bag',this._freedialogui);
        spine_bag.getComponent(sp.Skeleton).setAnimation(0,'animation3',false);
        let bg = cc.find('nodeui/nicewin/item'+index+'/bg',this._freedialogui);
        bg.active = true;

        let spnum = cc.find('num',bg).getComponent(cc.Sprite);
        this.changeNumSprite(spnum,this.getAtlasSpriteName(num));
        //同时置灰背景和数字
        this.changeSpriteGray(bg.getComponent(cc.Sprite),true);
        this.changeSpriteGray(spnum,true);
    },

    // 播放线路完成
    async onRecvPlayLineFinish (){
        return new Promise((success)=>{
            console.log("###线路播放完成！");
            this._nextpromise = success;
            let gameinfo = cc.vv.gameData.getGameInfo();
            if(gameinfo.select&&gameinfo.select.state&&gameinfo.select.rtype == 3){
                if(gameinfo.booms.indexs&&gameinfo.booms.indexs.info.length > 0){
                    this.boomsIndexfly(gameinfo.booms);
                }else{
                    this.showBoomsSelect();
                }
                return;
            }
            if(gameinfo.booms){
                console.log("###普通免费次数 "+gameinfo.freeCnt);
                if(gameinfo.freeCnt == gameinfo.allFreeCnt){
                    //显示进入免费
                    Global.playHSEffect(this._soundCfg.bell);
                    this.scheduleOnce(()=>{
                        this.showYouWinUI(0,gameinfo.freeCnt);
                    },2);
                }else{
                    console.log("###免费游戏状态 ");
                    //如果是免费游戏状态
                    if(gameinfo.booms.indexs&&gameinfo.booms.indexs.info.length > 0){
                        this.boomsIndexfly(gameinfo.booms);
                    }else{
                        this.showOperateResult();
                        //cc.vv.gameData.clearFreeData();
                    }
                }
                
            }else{
                if(this._nextpromise){
                    this._nextpromise();
                    this._nextpromise = null;
                }
            }
        })
    },

    //booms大奖特效飞下效果
    async coinFlyToBottom(){
        return new Promise((success)=>{
            if(this._upCount < 1){
                success();
            }else{
                let curlevel = this._upCount+1;
                let startnode = cc.find("topshow/topshow"+curlevel,this._freeGameNode);
                let winnode = cc.find('safe_node/LMSlots_Bottom/winBg',this.node);
                let flyeffect = cc.find('jinbijieshou',this._freeGameNode);
                let lizibaozha = cc.find('safe_node/lizibaozha',this.node);
                let insteff = cc.instantiate(flyeffect);
                insteff.parent = flyeffect.parent.parent;
                insteff.active = true;
                lizibaozha.position = lizibaozha.parent.convertToNodeSpaceAR(winnode.convertToWorldSpaceAR(cc.v2(0,0)))
                let beiginPos = insteff.parent.convertToNodeSpaceAR(startnode.convertToWorldSpaceAR(cc.v2(0,0)))
                insteff.position = beiginPos
                Global.playHSEffect(this._soundCfg.symbol_fly);
                let aimpos = insteff.parent.convertToNodeSpaceAR(winnode.convertToWorldSpaceAR(cc.v2(0,0)))
                cc.tween(insteff).to(0.5,{position:aimpos}).call(()=>{
                    let freewin = cc.vv.gameData.GetGameTotalFreeWin();
                    cc.vv.gameData.GetBottomScript().SetWin(freewin);
                    lizibaozha.active = true;
                    lizibaozha.getComponent(cc.ParticleSystem).resetSystem();
                    insteff.destroy();
                    success();
                }).start();
            }
        })
    },

    //booms index飞金币
    boomsIndexfly(booms){
        let aimnode = cc.find('safe_node/free_game/topshow16',this.node);
        let flyeffect = cc.find('safe_node/free_game/getcoin',this.node);

        let indexinfo = booms.indexs.info;
        for(let i=0;i<indexinfo.length;i++){
            let info = indexinfo[i];
            let insteff = cc.instantiate(flyeffect);
            insteff.parent = flyeffect.parent.parent;
            insteff.active = true;
            let symbol = cc.find('safe_node/slots',this.node).getComponent('LuckyCat_Slots').GetSymbolByIdx(info.idx);
            let beiginPos = insteff.parent.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)))
            insteff.position = beiginPos
            Global.playHSEffect(this._soundCfg.symbol_fly);
            let aimpos = insteff.parent.convertToNodeSpaceAR(aimnode.convertToWorldSpaceAR(cc.v2(0,0)))
            let xpos = this.getPosOffset(info.idx,beiginPos.x*i);
            let bezier = [cc.v2(beiginPos.x, beiginPos.y), cc.v2(xpos, beiginPos.y), aimpos];
            insteff.runAction(cc.sequence(cc.bezierTo(0.6, bezier), cc.callFunc(()=>{
                //播放能量收集
                this.playWildChange(symbol);
                this.playCollectJieshou(booms.indexs.total);
                insteff.destroy();
            })));
        }
        Global.playHSEffect(this._soundCfg.bonus_collect);
        this.scheduleOnce(()=>{
            Global.playHSEffect('symbol_fly');
            Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_REFUSH_ENERGY);
        },0.5);
        this.scheduleOnce(()=>{
            let gameinfo = cc.vv.gameData.getGameInfo();
            if(gameinfo.select&&gameinfo.select.state&&gameinfo.select.rtype == 3){
                this.showBoomsSelect();
            }else{
                this.showOperateResult();
            }
        },2);
    },

    //显示操作结果
    async showOperateResult(){
        if(cc.vv.gameData.GetFreeTime() > 0){
            this.handSpine();
        }else{
            await this.coinFlyToBottom();
            await cc.vv.gameData.awaitTime(1);
            this.showYouWinUI(1);
        }
    },

    //获取位置的偏移值
    getPosOffset(idx,srcx){
        if(idx ==1||idx==2||idx==6||idx==7||idx==11||idx==12){
            return -srcx;
        }
        return srcx;
    },

    //播放收集结束动画
    playCollectJieshou(total){
        let jieshou =  cc.find('safe_node/free_game/topshow16/collectjieshou',this.node);
        jieshou.active = true;
        jieshou.getComponent(sp.Skeleton).setAnimation(0,'animation',false);
        let shownum =  cc.find('safe_node/free_game/topshow16/shownum',this.node);
        let srcnum = parseInt(shownum.getComponent(cc.Label).string);
        Global.doRoallNumEff(shownum,srcnum,srcnum+total,1.5,null,null,0,true)
    },

    //能量收集飞效果
    playWildChange(symbol){
        console.log('免费内刷新能量');
        symbol.playFreeCollectAction();
    },

    //直接初始化层级(不需要展示效果)
    initUpIndex(upnum){
        if(upnum == 0)
            return;
        for(let i=0;i<upnum;i++){
            this.changeGrayLastTopShow(i,true);
        }
        let topshow = cc.find("topshow/topshow"+upnum,this._freeGameNode);
        this.playArrowAnimation(topshow,upnum,true);
        //显示spine框

        let kuang = cc.find("kuang_xz",this._freeGameNode);
        kuang.active = true;
        let aniname = this.getKuangAnimation(upnum);
        kuang.getComponent(sp.Skeleton).setAnimation(0,aniname,true);
        kuang.position = this._freeGameNode.convertToNodeSpaceAR(topshow.convertToWorldSpaceAR(cc.v2(0,0)));
    },

    //展示选中钱袋后播放获取coin提升
    playGetCoinUp(upnum){
        let upindex = this._upCount+1;
        if(this._upCount+upnum>16){
            upnum = 16-this._upCount;
            this._upCount = 16;
        }else{
            this._upCount += upnum;
        }

        let kuang = cc.find("kuang_xz",this._freeGameNode);
        this.schedule(()=>{
            kuang.active = true;
            let topshow = cc.find("topshow/topshow"+upindex,this._freeGameNode);
            let aniname = this.getKuangAnimation(upindex);
            kuang.getComponent(sp.Skeleton).setAnimation(0,aniname,true);
            kuang.position = this._freeGameNode.convertToNodeSpaceAR(topshow.convertToWorldSpaceAR(cc.v2(0,0)));

            this.changeGrayLastTopShow(upindex-1,true);
            this.playArrowAnimation(topshow,upindex,upindex == this._upCount);
            Global.playHSEffect(this._soundCfg.bonus_up);
            if(upindex == this._upCount){
                this.showOperateResult();
            }
            upindex++;
        },1,upnum-1);
    },

    //获取kuang动作名
    getKuangAnimation(upindex){
        switch (upindex) {
            case 1:
            case 2:return 'animation1';
            case 3:
            case 4:return 'animation2';
            case 5:
            case 6:return 'animation3';
            case 7:
            case 8:return 'animation4';
            case 9:return 'animation5';
            case 10:return 'animation6';
            case 11:return 'animation7';
            case 12:return 'animation8';
            case 13:return 'animation9';
            case 14:return 'animation10';
            case 15:return 'animation11';
            case 16:return 'animation12';
        }
        return 'animation12';
    },

    //播放指示动画
    playArrowAnimation(topshow,upindex,isover){
        if(upindex > 8){
            let kuang = cc.find('kuang_jt03',topshow);
            if(kuang){
                kuang.active = true;
                kuang.getComponent(sp.Skeleton).setAnimation(0,'animation1',isover);
            }
            kuang = cc.find('kuang_jt04',topshow);
            if(kuang){
                kuang.active = true;
                kuang.getComponent(sp.Skeleton).setAnimation(0,'animation1',isover);
            }
        }else{
            let arrow = cc.find('kuang_jt01',topshow);
            if(arrow){
                arrow.active = true;
                arrow.getComponent(sp.Skeleton).setAnimation(0,'animation1',isover);
            }
            this.scheduleOnce(()=>{
                let arrow2 = cc.find('kuang_jt02',topshow);
                if(arrow2){
                    arrow2.active = true;
                    arrow2.getComponent(sp.Skeleton).setAnimation(0,'animation1',isover);
                }
            },0.5);
        }
    },

    //置灰上一对象
    changeGrayLastTopShow(index,isgray){
        if(index <= 0)
            return;
        let topshow = cc.find("topshow/topshow"+index,this._freeGameNode);
        let obj = topshow.getChildByName('arrow');
        if(obj){
            this.changeSpriteGray(obj.getComponent(cc.Sprite),isgray);
        }
        obj = topshow.getChildByName('shownum');
        if(obj){
            this.changeSpriteGray(obj.getComponent(cc.Label),isgray);
        }
        obj = topshow.getChildByName('bg');
        if(obj){
            this.changeSpriteGray(obj.getComponent(cc.Sprite),isgray);
        }
        obj = topshow.getChildByName('leftarrow');
        if(obj){
            this.changeSpriteGray(obj.getComponent(cc.Sprite),isgray);
        }
        obj = topshow.getChildByName('rightarrow');
        if(obj){
            this.changeSpriteGray(obj.getComponent(cc.Sprite),isgray);
        }

        obj= cc.find('kuang_jt03',topshow);
        if(obj){
            obj.active = false;
        }
        obj = cc.find('kuang_jt04',topshow);
        if(obj){
            obj.active = false;
        }
        obj = cc.find('kuang_jt01',topshow);
        if(obj){
            obj.active = false;
        }
        obj = cc.find('kuang_jt02',topshow);
        if(obj){
            obj.active = false;
        }
        
    },

    //恢复置灰效果
    resetGrayTopShow(){
        for(let i=1;i<16;i++){
            this.changeGrayLastTopShow(i,false);
        }
    }
});
