/**墨西哥帅哥-符号表 
 * 
*/
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    //重写
    StartMove:function(){
        this._super()
        this.SetText()
        
    },

    //显示bonus中奖
    ShowBonus:function(bShow){
        if(this._data){
            if(bShow){
                this.SetText(this._data.num)
                this.ShowWin()
            }
            else{
                this.SetText()
            }
        }
    },

    //
    ShowMask:function(bShow){
        let mask = cc.find("mask",this.node)
        mask.active = bShow
    },

    SetText:function(num){
        // let txt = cc.find("coin_num",this.node)
        // if(num){
        //     txt.active = true
        //     txt.getComponent(cc.Label).string = Global.formatNumShort(num)
        // }
        // else{
        //     txt.active = false
        // }
        
    },


    //播放收集能量动作
    PlayCollectAction:function(){
        let self = this
        if((this._id != 2)&&(this._id != 3)&&(this._id != 4)&&(this._id != 5)){
            return
        }
       
        //先播放scatter动画
        let cfg = cc.vv.gameData.getGameCfg();
        let tongyongnode = cc.find("tongyongdi",this.node);
        let wnode = cc.find(cfg.symbol[this._id].win_node,this.node);
        tongyongnode.active = true;
        wnode.active = true;
        tongyongnode.getComponent(sp.Skeleton).setAnimation(0,"animation1",false);
        wnode.getComponent(sp.Skeleton).setAnimation(0,"animation1",false);

        //同时实例化scatter对象 移动用
        let flyNode = cc.instantiate(this.node);
        flyNode.active = false;
        let parentNode = cc.find('Canvas/safe_node')
        flyNode.parent = parentNode
        let beiginPos = parentNode.convertToNodeSpaceAR(this.node.convertToWorldSpaceAR(cc.v2(0,0)))
        flyNode.position = beiginPos

        //开始移动
        this.node.runAction(cc.sequence(cc.delayTime(0.5),cc.callFunc(()=>{
            tongyongnode.active = false;
            wnode.active = false;

            flyNode.active = true
            let targetNode = cc.find('Canvas/safe_node/node_energy/spr_left')
            let tarPos = parentNode.convertToNodeSpaceAR(targetNode.convertToWorldSpaceAR(cc.v2(0,0)))
            cc.tween(flyNode).bezierTo(0.5,cc.v2(beiginPos.x,beiginPos.y),cc.v2(tarPos.x,beiginPos.y),cc.v2(tarPos.x,tarPos.y),{scale:0.3})
                    .call(() => {
                       
                        flyNode.destroy()
                    }).start()
        })
        ));
    },

    //播放进入免费动画
    playScatterAnimation(){
        if((this._id != 2)&&(this._id != 3)&&(this._id != 4)&&(this._id != 5)){
            return
        }
        let cfg = cc.vv.gameData.getGameCfg();
        let wnode = cc.find(cfg.symbol[this._id].win_node,this.node);
        wnode.active = true;
        wnode.getComponent(sp.Skeleton).setAnimation(0,"animation2",true);
    },

    //关闭动画节点
    resetScatterShow(){
        this.node.getChildByName('num').active = false;
        this.node.getChildByName('w10').active = false;
        this.node.getChildByName('w11').active = false;
        this.node.getChildByName('w12').active = false;
        this.node.getChildByName('w13').active = false;

    },
    
    //显示数值
    showSymbolNumber(num){
        let numnode = cc.find('num',this.node);
        numnode.active = true;
        numnode.getComponent(cc.Label).string = Global.formatNumShort(num);
    },


    //飞到能量条位置
    playFreeCollectAction:function(){
        let self = this
        if(this._id != 14){
            return
        }
       
        //先播放scatter动画
        let cfg = cc.vv.gameData.getGameCfg();

            //同时实例化scatter对象 移动用
            let flyNode = cc.instantiate(this.node);
            let parentNode = cc.find('Canvas/safe_node')
            flyNode.parent = parentNode
            let beiginPos = parentNode.convertToNodeSpaceAR(this.node.convertToWorldSpaceAR(cc.v2(0,0)))
            flyNode.position = beiginPos

            let wnode = cc.find(cfg.symbol[this._id].win_node,flyNode);
            wnode.active = true;
            let ske = wnode.getComponent(sp.Skeleton);
            ske.setAnimation(0,"animation1",false);

            //开始移动
            this.node.runAction(cc.sequence(cc.delayTime(0.5),cc.callFunc(()=>{
                let targetNode = cc.find('Canvas/safe_node/node_energy/spr_left')
                let tarPos = parentNode.convertToNodeSpaceAR(targetNode.convertToWorldSpaceAR(cc.v2(0,0)))
                cc.tween(flyNode).bezierTo(0.5,cc.v2(beiginPos.x,beiginPos.y),cc.v2(tarPos.x,beiginPos.y),cc.v2(tarPos.x,tarPos.y),{scale:0.3})
                        .call(() => {
                            flyNode.destroy()
                        }).start()
            })
            ));
    },
});
